// 边表（核实边）：两个节点之间有类型、有引文的必然联系。
//
// 为什么单独一张表（库主 2026-09-04 定，照 eco-web 的 links.js）：条目里的 rel 只记「互见」，
// 不说是什么关系；提及图与维基出链只证明常被并提。真正的关系——谁是谁的父亲、谁发动了
// 哪一战、哪篇赋写的是哪一仗——得有动词、有出处，才配上卡、进权重。
//
// 三条规矩：
//   ① 一个事实存一行。逆向读法由 VERBS 表配（父↔子、发动↔发动者），加载时展开两头，
//      两头各存一行会漂（改了一头忘另一头，lint 查不出）。
//   ② 动词闭集。用到不在表里的动词，先在这里登记（含逆读与角色名），tools/lint-links.py
//      查到未登记动词即报错；带 `?` 前缀的是员拟的新动词，候库主裁，lint 只警告。
//   ③ 两头都写全带类型前缀的节点 id：
//        ev:条名（events.js 的 n，全库唯一）   r:本名@政权键（js/data-*.js 的 n@d）
//        p:维基条目名（非君主人物，见 persons.js）   d:政权键（dynasties.js）
//        loc:地名（events.js p 字段里的写法）
//   方向按族定死：血亲 长辈→晚辈；承继 前任→继任；人对事 人→事；作品 作品→对象；
//   事对地 事→地（与 p 字段同向）；时段 时段→君主。
//
// 行由 tools/mining/links_merge.py 从各员载荷合并进来（幂等，按 src+verb+dst 去重），
// 机械生成的边（血亲、p 角色展开、时段涵盖）另在 links-gen.js，不混进这张手核表。
// 每行：l(源, 动词, 靶, 引文, 层级 1 库内长文或一手逐字／2 维基条目／3 推断, 注, 存疑)。

