export const LINKS = [];
/** 登记一条核实边。src/dst 带类型前缀；lv 1 库内长文或一手逐字／2 维基条目／3 推断。 */
function l(src, verb, dst, cite, lv, note, q) {
  // q：存疑（库主 2026-09-04 定，与夏朝、器物作者一类「允许存疑」同一精神）——两说并存、世系打架、称谓与父名不合等，
  // 写一句缘由；空串即无疑。卡上带「存疑」角标，权重按存疑边打折另议。
  LINKS.push({ src, verb, dst, cite: cite || '', lv: lv || 1, note: note || '', q: q || '' });
}

