  l('p:陳開', '领衔', 'ev:广东洪兵起义', '库内 yl：「三会公推陈开、李文茂为盟主」', 1, '长文明言「洪兵作为一个统一名号与统一号令，比各地起事晚了数月才成形」，故发动与领衔两角色两行', '');
  l('p:李文茂', '领衔', 'ev:广东洪兵起义', '库内 yl：「三会公推陈开、李文茂为盟主」', 1, '长文另记「李文茂部陣亡者數萬人」，惟数字三个量级不取一说', '');
  l('p:葉名琛', '平定', 'ev:广东洪兵起义', '库内 yc：「两广总督叶名琛督师镇压，各源所记死者量级与范围皆不一，不取一说」', 1, '此边只据 yc 的「督师镇压」；《清史稿》那几条剿捕敕令长文明言不指认即是本案，故不据以立边', '');
