  l('r:姬发@xzhou', '创制', 'ev:分封制', '库内 yl 引《史记·周本纪》：「封諸侯，班賜宗彝，作《分殷之器物》」', 1, '长文自陈「这套制度没有开张之日，只有第一批封国」——创制一头系于首封之人，不系某年某诏；起年本身系断代工程推定值', '');
  l('p:姜太公', '受封', 'ev:分封制', '库内 yl 逐字：「於是封功臣謀士，而師尚父為首封。封尚父於營丘，曰齊」', 1, '受封一头闭集无词，拟?受封；主循环不采则落「当事」。师尚父即吕尚，维基正名姜太公', '');
