  l('p:富辰', '当事', 'ev:分封制', '库内 yl 逐字《左传·僖公二十四年》：「故封建親戚以蕃屏周」', 1, '长文「屏藩这层意思，是三百多年后一个大夫替它说出来的」；此语出富辰谏周襄王之辞，是劝谏不是制度说明书，长文特为提醒', '');
  l('p:李斯', '主谋', 'ev:焚书坑儒', '一手《史記》卷六（维基文库 action=raw 逐字）：「丞相臣斯昧死言……臣請史官非秦記皆燒之」', 1, '本条无 yl，yc 亦不点名，此边出一手。李斯只在焚书一头；坑一头本纪不见其名，故取「主谋」不取「发动」', '');
  l('r:嬴政@qin', '发动', 'ev:焚书坑儒', '一手《史記》卷六：李斯奏末「制曰：可」；坑一头「乃自除犯禁者四百六十餘人，皆阬之咸陽」', 1, '下旨的与动手的分两行：李斯奏请（主谋），始皇制可并亲自案问诸生（发动）', '');
  l('p:淳于越', '当事', 'ev:焚书坑儒', '一手《史記》卷六：「博士齊人淳于越進曰：臣聞殷周之王千餘歲，封子弟功臣，自為枝輔」', 1, '其议是李斯奏请焚书的由头（始皇下其议，斯乃言）；所议正是库内分封制条之事，两条在此一线相连', '');
  l('p:扶苏', '被贬', 'ev:焚书坑儒', '一手《史記》卷六：「始皇怒，使扶蘇北監蒙恬於上郡」', 1, '谏坑诸生而被遣往上郡，是坑一头唯一有名的连带者', '');
  l('r:刘彻@xhan', '创制', 'ev:刺史', '库内 yl 逐字《汉书·百官公卿表》：「武帝元封五年初置部刺史，掌奉詔條察州……秩六百石，員十三人」', 1, '以六百石之官察二千石之郡守，是这套设计最要紧的一笔', '');
  l('r:刘骜@xhan', '更制', 'ev:刺史', '库内 yl 逐字：「成帝綏和元年更名牧，秩二千石」', 1, '改动既有制度（更名、改秩、复旧）闭集无词：创制不合，改良带评价，故拟?更制。不采则落「当事」', '');
  l('r:刘欣@xhan', '更制', 'ev:刺史', '库内 yl 逐字：「哀帝建平二年復爲刺史，元壽二年復爲牧」', 1, '一朝两改，长文指与同这三年间三公的反复是同一次通盘调整的两面', '');
  l('p:郑吉', '创制', 'ev:西域都护府', '一手《漢書》卷七十：「遂并護車師以西北道，故號都護……都護之置自吉始焉」', 1, '本条无 yl，yc 只写「西汉在西域设置」不点名；汉书自己把置府一事系在郑吉身上', '');
  l('r:刘询@xhan', '当事', 'ev:西域都护府', '一手《漢書》卷七十：「上嘉其功效，迺下詔曰：都護西域騎都尉鄭吉，拊循外蠻」', 1, '下旨的与动手的分两行：汉书把置府归郑吉，宣帝一头所见只是嘉功之诏，不写作创制', '');
  l('r:杨坚@sui', '创制', 'ev:三省六部制', '一手《隋書》卷二十八百官下：「髙祖旣受命，改周之六官……置三師、三公及尚書、門下、内史、秘書、内侍等省」', 1, '本条无 yl，yc 只写「隋唐定型后历代承袭」不点名。隋制三省作尚書、門下、内史（唐始改中書），六曹作吏部、禮部、兵部、都官、度支、工部，与 yc 所记名目有出入，另见存疑节', '');
  l('r:杨坚@sui', '创制', 'ev:科举取士之始', '一手《隋書》卷一高祖紀上，開皇七年：「春正月癸巳，有事于太廟。乙未，制諸州歲貢三人」', 1, '本条 y=587 正是开皇七年；yc 只写「肇始于隋」不点名，此边出一手', '');
  l('r:杨广@sui', '敕修', 'ev:开凿大运河', '库内 yc：「隋炀帝下令开凿贯通南北的大运河」', 1, '下旨一头。动手的一头长文无人名——麻叔谋之说出唐人小说《开河记》，不在库内长文内，不立（见候选未立节）', '');
  l('r:李世民@tang', '创制', 'ev:安西都护府', '一手《舊唐書》卷三太宗下，貞觀十四年：「九月……乙卯，於西州置安西都護府」', 1, '本条 y=640 正是贞观十四年；yc 只写「唐朝设于西域」不点名，本纪系太宗，别无主名', '');
  l('p:侯君集', '当事', 'ev:安西都护府', '一手《舊唐書》卷三：「交河道行軍大總管侯君集平高昌，以其地置西州」', 1, '八月平高昌置西州在前，九月于西州置安西都护府在后；他平的是高昌，不是都护府，故取当事不取平定', '');
  l('r:武曌@tang', '称制', 'ev:武周革命', '库内 yc：「武则天废唐称帝，改国号为周」', 1, '长文原字作「称帝」，闭集「称制」（库主 09-04 采）取其义；本条讫年 705 神龙革命迫其禅位', '');
  l('r:李显@tang', '被立', 'ev:武周革命', '库内 yc：「705年神龙革命迫其禅位于唐中宗，唐朝复辟」', 1, '系于本条讫端；神龙革命库内无独立条，此行只记受禅复位一层，不代它', '');
  l('p:賀拔延嗣', '当事', 'ev:节度使', '一手《唐會要》卷七十八：「景雲二年四月。賀拔延嗣除涼州都督。充河西節度使。此始有節度之號」', 1, '本条 y=711 正是景云二年；yc 通篇无人名，此边出一手。他是第一个带此号的人，不是创制者——会要只说「此始有節度之號」，未记某帝某诏立此制', '');
  l('r:李隆基@tang', '创制', 'ev:翰林院', '一手《唐會要》卷五七：「元宗以四隩大同……由是始選朝官有詞藝學識者。入居翰林。供奉敕旨」', 1, '库内 yl 引同卷而只作「至二十六年，始以翰林供奉，改稱學士」，主语空着；同页上文点名，惟文库作「元宗」（宋人避「玄」讳），即唐玄宗李隆基', '');
  l('p:溫大雅', '当事', 'ev:翰林院', '库内 yl 逐字《唐会要》卷五十七：「武德已後，有溫大雅、魏徵、李百藥……時召入草制，未有名目」', 1, '定名之前入直草制的一层（武德—乾封），非 738 年定制的当事人；长文「翰林的来历分三层」的头一层', '');
  l('p:魏徵', '当事', 'ev:翰林院', '库内 yl 逐字：「武德已後，有溫大雅、魏徵、李百藥、岑文本、褚遂良、許敬宗、上官儀等，時召入草制」', 1, '同上，前史一层', '');
  l('p:李百药', '当事', 'ev:翰林院', '库内 yl 逐字：「武德已後，有溫大雅、魏徵、李百藥、岑文本……時召入草制，未有名目」', 1, '同上，前史一层', '');
  l('p:岑文本', '当事', 'ev:翰林院', '库内 yl 逐字：「有溫大雅、魏徵、李百藥、岑文本、褚遂良……時召入草制，未有名目」', 1, '同上，前史一层', '');
  l('p:褚遂良', '当事', 'ev:翰林院', '库内 yl 逐字：「李百藥、岑文本、褚遂良、許敬宗、上官儀等，時召入草制，未有名目」', 1, '同上，前史一层', '');
  l('p:許敬宗', '当事', 'ev:翰林院', '库内 yl 逐字：「岑文本、褚遂良、許敬宗、上官儀等，時召入草制，未有名目」', 1, '同上，前史一层', '');
  l('p:上官仪', '当事', 'ev:翰林院', '库内 yl 逐字：「褚遂良、許敬宗、上官儀等，時召入草制，未有名目」', 1, '同上，前史一层', '');
  l('r:李炎@tang', '发动', 'ev:会昌灭佛', '库内 yc：「唐武宗在会昌年间大举灭佛，颁敕焚毁寺院、勒令僧尼还俗」', 1, '本条无 yl。「三武一宗」并称的另三位（北魏太武帝、北周武帝、后周世宗）是类比不是当事，不立', '');
  l('r:赵匡胤@nsong', '发动', 'ev:宋太祖黜白起', '库内 yl 逐字《宋史·礼志八》：「帝幸廟，歷觀圖壁，指白起曰：『此人殺已降，不武之甚，何受享於此？』命去之」', 1, '长文特为辟谣：网上流传的「起殺已降……何為受享於此」与原文不合，不采。白起「罢祀」一行库内已有，此处不重出', '');
  l('r:耶律德光@liao', '传入', 'ev:汉服', '库内 yl 逐字《辽史·仪卫志二》：「大同元年正月朔，太宗皇帝入晉……是年北歸，唐晉文物，遼則用之」', 1, '本条 y=947 即大同元年。同卷本纪载晋之卤簿法物「悉送上京」——制度是装车运走的；「传入」取其自后晋入辽一层，非域外传入之义', '');
  l('p:文震亨', '当事', 'ev:汉服', '库内 yl：「『汉制』是到文震亨笔下才写成『汉服』的」（《长物志》四库本卷九作「漢服」）', 1, '词史一层，非制度当事。元末叶子奇《草木子》同一张断代单子作「漢制」，本轮逐字核过两书；本条只做这个词的编年', '');
  l('r:赵昀@ssong', '发动', 'ev:王安石黜孔庙', '库内 yl 逐字《宋史·理宗本纪二》：「為萬世罪人，豈宜從祀孔子廟庭，黜之」', 1, '淳祐元年（1241）诏，与理学五子入从祀同一道诏的前后脚。王安石「罢祀」一行库内已有，此处不重出', '');
  l('p:周敦颐', '受祀', 'ev:王安石黜孔庙', '库内 yl 逐字：「以周敦颐、张载、程颢、程颐、朱熹五人『列诸从祀』」', 1, '理学五子请进来与王安石清出去写在同一道诏里，故同挂本条', '');
  l('p:張載 (北宋)', '受祀', 'ev:王安石黜孔庙', '库内 yl 逐字：「以周敦颐、张载、程颢、程颐、朱熹五人『列诸从祀』」', 1, '维基「张载」为消歧义页，正名张载 (北宋)', '');
  l('p:程顥', '受祀', 'ev:王安石黜孔庙', '库内 yl 逐字：「以周敦颐、张载、程颢、程颐、朱熹五人『列诸从祀』」', 1, '', '');
  l('p:程颐', '受祀', 'ev:王安石黜孔庙', '库内 yl 逐字：「以周敦颐、张载、程颢、程颐、朱熹五人『列诸从祀』」', 1, '沿用库内已登记 id（persons.js 作简体「程颐」，其兄维基正名作繁体「程顥」，两兄弟 id 形不齐，见存疑节）', '');
  l('p:朱熹', '受祀', 'ev:王安石黜孔庙', '库内 yl 逐字：「以周敦颐、张载、程颢、程颐、朱熹五人『列诸从祀』」', 1, '', '');
  l('r:赵桓@nsong', '发动', 'ev:王安石黜孔庙', '库内 yl 逐字《宋史》本传：「欽宗時，楊時以為言，詔停之」', 1, '1126 年停的是孔庙从祀这一份，不是 1241 年那一次彻底除名。长文警「两份荣典，两次撤销，常被搅成一件事」', '');
  l('p:楊時 (宋朝)', '当事', 'ev:王安石黜孔庙', '库内 yl 逐字：「欽宗時，楊時以為言，詔停之」', 1, '1126 年建言者。维基「杨时」为消歧义页，正名楊時 (宋朝)', '');
  l('r:赵构@ssong', '发动', 'ev:王安石黜孔庙', '库内 yl 逐字：「高宗用趙鼎、呂聰問言，停宗廟配享，削其王封」', 1, '本行记的是太庙配享那一份与削王封，不是孔庙——长文正为分开这两份而写，读卡时须照此分', '');
  l('p:赵鼎', '当事', 'ev:王安石黜孔庙', '库内 yl 逐字：「高宗用趙鼎、呂聰問言，停宗廟配享，削其王封」', 1, '太庙那一份的建言者。同列的吕聪问维基无条目，p: id 无从落，见存疑节', '');
  l('r:朱元璋@ming', '创制', 'ev:大封天下城隍', '库内 yl 逐字《明太祖实录》卷三十八：「明有禮樂，幽有鬼神，若城隍神者歷代所祀，宜新封爵」', 1, '洪武二年正月对中书及礼官语，遂封京都城隍为承天鑒國司民升福明靈王，府州县各按品级封公侯伯', '');
  l('r:朱元璋@ming', '更制', 'ev:大封天下城隍', '库内 yl 逐字：「洪武三年即『詔去封號』」，又令各庙屏去他神、毁塑像而立木主', 1, '同一人前后两诏，是两个事实故两行：先封成王侯公伯，一年之内又一律削平。不采?更制则落「当事」', '');
  l('p:蕭綸', '当事', 'ev:大封天下城隍', '库内 yl 逐字《南史》卷五三：邵陵王萧纶至郢州「祭城隍神，將烹牛，有赤蛇繞牛口出」', 1, '前史层，梁大宝元年（550），距本条锚年八百一十九年。《隋书》五行志另系于武陵王萧纪，两说并存', '');
  l('p:慕容儼', '当事', 'ev:大封天下城隍', '库内 yl 逐字《北齐书·慕容俨传》：「於是順士卒之心，乃相率祈請」', 1, '前史层，北齐天保六年（555）守同一座郢城被围而祷于城隍神', '');
  l('p:張說', '当事', 'ev:大封天下城隍', '库内 yl 逐字：张说开元五年（717）《祭城隍文》「城隍以積陰為德，致和產物，助天育人，人之仰恩，是關祀典」', 1, '前史层，唐代地方官祭城隍成文体的最正式一笔；与四十二年后李阳冰「祀典無之」一句正相反', '');
  l('p:李阳冰', '当事', 'ev:大封天下城隍', '库内 yl 逐字：乾元二年（759）缙云县令李阳冰求雨「與神約曰：五日不雨，將焚其廟」', 1, '前史层。其迁庙记首句作「城隍神祀典無之，吳越有之」——到八世纪中叶城隍算不算国家祀典，唐人自己没说定', '');
  l('r:朱元璋@ming', '创制', 'ev:海禁政策', '一手《明太祖实录》卷七十（洪武四年十二月）：「詔……仍禁瀕海民不得私出海」', 1, '本条无 yl，yc 只写「明朝厉行」不点名，此边出一手。本条 y=1371 正是洪武四年；该诏正文是命靖海侯吴祯籍方国珍所部为军，禁海一句附在其后', '');
  l('r:朱厚熜@ming', '发动', 'ev:大礼议', '库内 yc：「明世宗登基后欲追尊生父兴献王为皇考」', 1, '本条无 yl。议礼一派的张璁、桂萼、席书皆不见于长文，不立', '');
  l('p:楊廷和', '对阵', 'ev:大礼议', '库内 yc：「与杨廷和、毛澄等正德旧臣坚持应尊孝宗为父的主张激烈冲突」', 1, '「对阵」本为战事政变族之词，此处取其两造相争之义', '');
  l('p:毛澄', '对阵', 'ev:大礼议', '库内 yc：「与杨廷和、毛澄等正德旧臣坚持应尊孝宗为父的主张激烈冲突」', 1, '同上', '');
  l('p:陳獻章', '受祀', 'ev:王守仁从祀', '库内 yl 逐字《明史·礼志四》：「十二年，又以陳獻章、胡居仁、王守仁從祀」', 1, '王守仁「受祀」一行库内已有，此处不重出', '');
  l('p:胡居仁', '受祀', 'ev:王守仁从祀', '库内 yl 逐字《明史·礼志四》：「十二年，又以陳獻章、胡居仁、王守仁從祀」', 1, '', '');
  l('p:申時行', '领衔', 'ev:王守仁从祀', '库内 yl：「到万历十二年（1584），赖申时行等大学士力主，心学才算被官方儒学正统收编」', 1, '长文原字作「力主」；此条无下诏者之名，不补神宗', '');
  l('p:桂萼', '当事', 'ev:王守仁从祀', '库内 yl 逐字：桂萼奏劾「守仁事不師古，言不稱師……傳習轉訛，背謬彌甚」', 1, '前史层，嘉靖八年（1529）王守仁病殁后停其世袭恤典、禁其学，去本条五十五年', '');
  l('r:努尔哈赤@qing', '创制', 'ev:八旗制度', '库内 yl 逐字《清史稿·太祖本纪》：「是歲，釐定兵制，初以黃、紅、白、黑四旗統兵，至是增四鑲旗，易黑爲藍」', 1, '长文顺带更正：原初四正色是黄红白黑，蓝旗自黑旗改出，非通常所说黄白红蓝；通行教科书系于 1601 年，清史稿本纪与兵志皆无此年，只记不采', '');
  l('r:皇太极@qing', '创制', 'ev:八旗制度', '库内 yl：「蒙古八旗定制于天聪九年（1635），汉军八旗历崇德二年（1637）分二旗、七年（1642）定制」', 3, '长文以年号系之，主语空着；天聪、崇德皆皇太极年号，本行系推断。满蒙汉二十四旗齐备一层，与努尔哈赤的满洲八旗分两行', '');
  l('p:多爾袞', '发动', 'ev:剃发易服', '库内 yl 逐字《清世祖实录》卷五：顺治元年五月「多爾袞兵至通州……諭令薙發」', 1, '颁与撤同属一角色故只一行：五月连下三道，至五月二十四日又自撤——「今聞甚拂民願……照舊束髮，悉從其便」，前后二十四日', '');
  l('r:福临@qing', '发动', 'ev:剃发易服', '库内 yl：「六月十五那道谕所给的理由，是皇帝自陈的『中外一家』『君犹父也民犹子也』」', 1, '本条锚 1645，取的正是生效的这一次。时顺治八岁、多尔衮摄政，谕以皇帝口吻自陈——下旨的名义与主之者分两行，不合并', '');
  l('p:多鐸', '当事', 'ev:剃发易服', '库内 yl 逐字：顺治二年六月初五「敕多鐸：各處文武軍民、盡令薙發。倘有不從、以軍法從事」', 1, '奉敕执行的一头', '');
  l('p:孙之獬', '当事', 'ev:剃发易服', '库内 yl 逐字《研堂见闻杂录》：「有山東進士孫之獬，陰為計，首剃髪迎降，以冀獨得歡心」', 1, '两说并存：私家笔记说是他一人激成此令，而长文自陈「官修一侧，那道疏一个字也没有」——《清史稿》本传通篇不及剃发，全卷只在冯铨传内记他先薙发被同僚拿作把柄，多尔衮反斥了言官', '');
  l('r:玄烨@qing', '敕修', 'ev:大清律例', '库内 yc：「历经康熙、雍正、乾隆三朝反复增删修订，才最终定型为《大清律例》」', 1, '本条无 yl，长文以朝系之，未记某年某诏。本条 y=1646 是顺治三年初纂，顺治一头长文无名，不补', '');
  l('r:胤禛@qing', '敕修', 'ev:大清律例', '库内 yc：「历经康熙、雍正、乾隆三朝反复增删修订，才最终定型为《大清律例》」', 1, '同上', '');
  l('r:弘历@qing', '敕修', 'ev:大清律例', '库内 yc：「历经康熙、雍正、乾隆三朝反复增删修订，才最终定型为《大清律例》」', 1, '同上；定型即在其朝', '');
  l('r:胤禛@qing', '创制', 'ev:设军机处', '库内 yc：「雍正七年因用兵准噶尔而设，原为临时军事指挥机构」', 1, '长文以年号系之；雍正七年即本条 y=1729，行为主体即清世宗胤禛本人', '');
  l('p:莊廷鑨', '当事', 'ev:清代文字狱', '库内 yl：「牵连到哪一层，一案可见：康熙二年（1663）庄廷鑨明史案」', 1, '本条是通条不是个案条（y=1774 只是坐标），此案自系其年；长文所据全祖望《鮚埼亭集外編》系清人文集追记，距事发约九十年，不当档案用', '');
  l('p:李令皙', '遇害', 'ev:清代文字狱', '库内 yl 逐字：「作序的李令皙父子皆伏法」', 1, '同上通条。其幼子年十六，「法司令其減供一歲，例得免死，充軍」，答曰「予見父兄死，不忍獨生」，卒不易其供而死——例本可以免他一死，他自己不受', '');
  l('r:弘历@qing', '创制', 'ev:金瓶掣签', '库内 yc：「乾隆帝为规范活佛转世认定而订立，载入《钦定藏内善后章程二十九条》」', 1, '本条无 yl', '');
  l('p:曾国藩', '创制', 'ev:湘军', '库内 yl：「次年曾国藩抵长沙与巡抚张亮基商办，把各地团练整合为湘勇」', 1, '咸丰二年十一月朝廷谕令在籍侍郎曾国藩帮办本省团练；咸丰四年（1854，本条 y）编成陆师十三营、水师十营，连伕役约一万七千人。湘勇改称湘军要到 1861 年', '');
  l('p:张亮基', '当事', 'ev:湘军', '库内 yl：「曾国藩抵长沙与巡抚张亮基商办」', 1, '时任湖南巡抚', '');
  l('p:奕訢', '发起', 'ev:洋务运动', '库内 yc：「奕訢、曾国藩、李鸿章、左宗棠等中央与地方大员发起」', 1, '长文原字即作「发起」，闭集无此词：发动属兵变战事族，领衔偏于一榜之首，故拟?发起。不采则落「领衔」', '');
  l('p:曾国藩', '发起', 'ev:洋务运动', '库内 yc：「奕訢、曾国藩、李鸿章、左宗棠等中央与地方大员发起」', 1, '同上', '');
  l('p:李鴻章', '发起', 'ev:洋务运动', '库内 yc：「奕訢、曾国藩、李鸿章、左宗棠等中央与地方大员发起」', 1, '同上', '');
  l('p:左宗棠', '发起', 'ev:洋务运动', '库内 yc：「奕訢、曾国藩、李鸿章、左宗棠等中央与地方大员发起」', 1, '同上', '');
  l('p:袁世凯', '创制', 'ev:小站练兵', '库内 yl：「1895年胡调任，袁世凯接办，在天津与塘沽之间的小站扩编训练……改称新建陆军」', 1, '本条 y=1895 即接办之年；仿德国陆军营制，是清朝第一支全西式编制训练装备的近代陆军', '');
  l('p:胡燏棻', '当事', 'ev:小站练兵', '库内 yl：「1894年原广西按察使胡燏棻奉命在天津用西法编练定武军十营」', 1, '本条前身一层，1894 年定武军四千七百余人；1895 年他调任，由袁世凯接办，故与袁分两行', '');
  l('r:载湉@qing', '发动', 'ev:戊戌变法', '库内 yc：「光绪帝在康有为、梁启超推动下推行政治改革，欲仿行君主立宪」', 1, '本条无 yl', '');
  l('p:康有为', '领衔', 'ev:戊戌变法', '库内 yc：「光绪帝在康有为、梁启超推动下推行政治改革」', 1, '长文原字作「推动」', '');
  l('p:梁启超', '领衔', 'ev:戊戌变法', '库内 yc：「光绪帝在康有为、梁启超推动下推行政治改革」', 1, '长文原字作「推动」', '');
  l('p:慈禧太后', '对阵', 'ev:戊戌变法', '库内 yc：「慈禧太后发动政变将其幽禁瀛台」', 1, '长文原字作「发动政变」，然她发动的是终结变法的戊戌政变而非变法本身；若与光绪同用「发动」，卡上会读成两人共发一事，故取「对阵」记其为相争的另一造。库内无独立政变条', '');
  l('p:谭嗣同', '遇害', 'ev:戊戌变法', '库内 yc：「谭嗣同等六人被杀」', 1, '六君子其余五人长文无名，不补', '');
  l('p:慈禧太后', '当事', 'ev:东南互保', '库内 yc：「八国联军进逼、慈禧太后对列强宣战之际，两广、两江等东南各省督抚拒不奉诏出兵」', 1, '宣战诏是本事的由头。长文未点名任何一位督抚（李鸿章、张之洞、刘坤一、袁世凯皆不见），互保一方无边可立', '');
  l('p:慈禧太后', '领衔', 'ev:清末新政', '库内 yc：「庚子事变后慈禧太后主导推行的最后一波改革」', 1, '长文原字作「主导推行」', '');
  // ── herart1 ──
  l('p:弗克·貝格曼', '命名', 'ev:小河墓地', '库内 yc：「1934年贝格曼命名，2000年后重新发掘」', 1, '瑞典考古学家，1934年为此墓地命名；重新发掘一节长文未出人名。闭集无命名一族，动词拟新', '');
  l('p:徐旭生', '当事', 'ev:二里头遗址', '库内 yl：「5月16日在当地干部带领下最先于二里头村发现遗迹遗物」', 1, '发现；长文同段自记他本人当时认为此处是商代早期都城西亳，不是夏都', '');
  l('p:许宏', '当事', 'ev:二里头遗址', '库内 yl：「1999年至今由许宏主持主动性发掘、重点转向聚落形态」', 1, '发掘；长文另引其「至迟在二里头文化四期，商人已经成为这一城邑的主人」一说', '');
  l('p:妇妌', '当事', 'ev:后母戊鼎', '库内 yc：「鼎为祭武丁之妻妇妌而铸」', 1, '受祭者，庙号母戊。铸者长文作「可能为祖庚或祖甲——推断，非定论」，故铸者一行不立', '');
  l('r:子旬@shang', '当事', 'ev:殷墟', '库内 yc：「公元前14世纪盘庚迁都于此，直至商亡历时约273年」', 1, '盘庚本名子旬，见库内先秦君主表；长文只言迁都、未言营造，故不用营造', '');
  l('p:毛公瘖', '当事', 'ev:毛公鼎', '库内 yc：「西周宣王年间青铜鼎，为毛公瘖所铸」', 1, '铸者。中文维基无此人条目（API 实测：毛公重定向至毛叔鄭、毛公厝为空页），id 取库内 yc 原字，候库主裁', '');
  l('r:嬴政@qin', '当事', 'ev:商鞅方升', '库内 yc：「底部另刻秦始皇二十六年统一度量衡诏书」', 1, '长文落句「始皇统一度量衡，用的正是秦国自己这件旧有标准器，非新制」；创制一行商鞅已在库', '');
  l('p:李冰', '营造', 'ev:都江堰', '库内 yc：「秦国蜀郡郡守李冰及其子约于公元前256至前251年主持修建」', 1, '「及其子」长文未出名，不硬立', '');
  l('r:嬴政@qin', '敕修', 'ev:秦始皇陵', '库内 yl 引《史记·秦始皇本纪》：「始皇初即位，穿治酈山，及并天下，天下徒送詣七十餘萬人」', 1, '陵为其自营，故用敕修不用营造；督工者长文未出名', '');
  l('r:嬴政@qin', '敕修', 'ev:兵马俑', '库内 yl：「一说随陵同建，始于始皇即位之初（前246）迄于其死（前210）」', 1, '营造年代长文三说并列不取一舍一，此为第一说；另二说系工期于统一之后', '');
  l('r:嬴政@qin', '当事', 'ev:泰山封禅', '库内 yc：「先到泰山行封礼，然后到梁父行禅礼」', 1, '长文作「开创帝王封禅泰山的先例」；闭集无主祀一族，用当事', '');
  l('p:曇曜', '营造', 'ev:云冈石窟', '库内 yc：「北魏和平初年沙门昙曜开五窟（今第16–20窟）」', 1, '昙五窟即今第16至20窟；迁洛后续凿者长文未出名', '');
  l('p:乐尊和尚', '营造', 'ev:敦煌石窟', '库内 yc：「前秦建元二年僧乐僔始凿，历十六国至元续修千年」', 1, '维基正题作乐尊和尚（乐僔重定向至此，API 实测），显示名从库内长文作乐僔', '');
  l('p:慧遠', '营造', 'ev:庐山东林寺', '库内 yc：「起于东晋太元十一年慧远创东林寺」', 1, '本条起年即系于此；维基正题作慧遠（东晋庐山慧远，API 实测非消歧义页）', '');
  l('p:朱熹', '营造', 'ev:庐山东林寺', '库内 yc：「讫于南宋朱熹复白鹿洞书院」', 1, '本条讫年即系于此。复书院非创寺，长文把两事并为庐山人文遗迹一脉；条名作东林寺而事在白鹿洞，拧', '');
  l('r:元宏@bwei', '敕修', 'ev:少林寺', '库内 yl 引《魏书·释老志》：「詔於少室山陰，立少林寺而居之，公給衣供」', 1, '高祖即孝文帝元宏。长文自核该句不带纪年，通行「太和十九年（495）」一手查无实据，只给太和宽窗', '');
  l('p:跋陀', '当事', 'ev:少林寺', '库内 yl 引《魏书·释老志》：「又有西域沙門名跋陀，有道業，深為高祖所敬信」', 1, '寺为其而立、公给衣供，非其营造，故用当事', '');
  l('r:胤禛@qing', '敕修', 'ev:少林寺', '库内 yl 引《少林寺志·营建》：「山门 雍正十三年奉敕创建」', 1, '本条 y2 取1735即此。长文作「是该志所载最后一次朝廷主持的营造」，未直书帝名，据雍正十三年系胤禛', '');
  l('p:石友三', '焚毁', 'ev:少林寺', '库内 yl：「中文维基记冯玉祥部石友三3月15日纵火焚法堂」', 1, '1928年。长文自记此事「出本库量程，只作卡面不作锚」，人数与卷数皆不采。闭集无焚毁一族，动词拟新', '');
  l('p:海通和尚', '营造', 'ev:乐山大佛', '库内 yc：「由僧人海通发起以镇水患」', 1, '起造年713是后世软锚——碑文只作「開元初，有沙門海通者」，无「開元元年」四字。维基正题作海通和尚（裸名海通是一种马鞭草科植物，不可用）', '');
  l('p:韦皋', '营造', 'ev:乐山大佛', '库内 yl 引韦皋碑：「貞元五年，有詔郡國伽藍，修舊起廢，遂命工徒，以俸錢五十萬佐其費」', 1, '完工年803由其所撰《嘉州凌云寺大弥勒石像记》末署自记；该碑未立条，撰者一行（著）无靶可落', '');
  l('p:章仇兼琼', '当事', 'ev:乐山大佛', '库内 yl 引韦皋碑：「其後有連帥章仇兼瓊者，持俸錢廿萬，以濟其經費」', 1, '只出俸钱济经费，碑文未言主持，故不用营造', '');
  l('p:金喬覺', '当事', 'ev:九华山', '库内 yc：「道场之名源于新罗王子金乔觉在此苦修、示寂后肉身不坏」', 1, '生卒年三说长文皆不裁；闵公舍地、道明出家、谛听渡海三节费冠卿记与《宋高僧传》全文皆无', '');
  l('p:李白', '命名', 'ev:九华山', '库内 yl 引《李太白文集》卷二十一：「予乃削其舊號，加以九華之目」', 1, '长文两层分记——唐人费冠卿《九华山化成寺记》只作「九華山古號九子山」不提改名，李白改名说要到宋人笔下才明说', '');
  l('p:白居易', '营造', 'ev:西湖', '库内 yc：「822年白居易任杭州刺史，浚湖筑堤」', 1, '本条起年即系于此。长文同句自辟：他筑的是白公堤早已不存，今白堤唐时即名白沙堤，与他无关', '');
  l('p:苏轼', '营造', 'ev:西湖', '库内 yc：「苏堤则确是苏轼的——1090年再浚西湖，以挖出的葑泥筑成」', 1, '与白居易一行恰成对照：一条堤是误记，一条堤是实的', '');
  l('p:慧持', '传为营造', 'ev:峨眉山', '库内 yl：「今日通行的说法是东晋隆安年间慧持入蜀建寺、初名普贤寺」', 1, '长文即在同段拆此说：《高僧传》卷六本传两处写峨眉皆作「欲」、全传无「普賢」二字，建寺供普贤一节是唐以后追记。闭集无传说层营造一族，动词拟新', '');
  l('r:朱翊钧@ming', '敕修', 'ev:峨眉山', '库内 yl：「万历帝为母祝七十寿，赐金建无梁砖殿、题「圣寿万年寺」金匾」', 1, '寺自此改称万年寺；本条主锚仍在宋初铸普贤铜像，不在此', '');
  l('p:松赞干布', '传为营造', 'ev:大昭寺', '库内 yc：「传为吐蕃赞普松赞干布所建，创寺年份诸说不一」', 1, '长文作「传为」，创寺年641／645／647三说本条取647，藏文史料（如《西藏王统记》）本轮未核。吐蕃不在库内君主表，故走 p:', '');
  l('p:尺尊公主', '当事', 'ev:大昭寺', '库内 yc：「相传为供奉尼泊尔尺尊公主携来的释迦牟尼八岁等身像而建」', 1, '长文作「相传」；建寺缘起系于她带来的那尊像', '');
  l('p:文成公主', '当事', 'ev:大昭寺', '库内 yl：「文成公主入藏（库内641条）后参与其事」', 1, '她带来的十二岁等身像本供小昭寺，两像后来对调，故后世多说她的佛像在大昭寺', '');
  l('p:玄奘', '营造', 'ev:大雁塔', '库内 yc：「玄奘为安置从天竺携归的佛像、舍利与梵夹，在大慈恩寺西院建塔」', 1, '永徽三年（652），初为五层', '');
  l('p:安重霸', '营造', 'ev:大雁塔', '库内 yl：「五代后唐长兴年间（930—933）西京留守安重霸修缮，自此基本定型」', 1, '长文自记这条层数变迁链各处转述一致而未溯《长安志》一类方志原文', '');
  l('r:李隆基@tang', '命名', 'ev:黄山得名', '库内 yl 引罗愿《新安志》卷三：「唐天寶六年六月十七日勅改為黄山」', 1, '长文未直书帝名，据天宝六载（747）系玄宗。罗愿同条小注当场自拆：「至天寳中好道家之説，故以黃帝為嘗遊于此，因名之耳」。闭集无命名一族，动词拟新', '');
  l('p:张择端', '创作', 'ev:清明上河图', '库内 yc：「北宋画家张择端所绘长卷」', 1, '', '');
  l('r:忽必烈@yuan', '敕修', 'ev:元上都', '库内 yc：「元朝陪都开平城，忽必烈即位前始建，1260年在此登基」', 1, '', '');
  l('p:劉秉忠', '营造', 'ev:元上都', '库内元大都条 yl 引《元史》卷一五七刘秉忠传：「帝命秉忠相地於桓州東灤水北，建城郭于龍岡，三年而畢，名曰開平」', 1, '引文出库内元大都条 yl；开平即本条那座城。同一人先建开平、后建大都，两都制两头都出其手', '');
  l('r:忽必烈@yuan', '敕修', 'ev:元大都', '库内 yl 引《元史》卷五十八地理志：「四年，始於中都之東北置今城而遷都焉」', 1, '本条锚年1267即此；另有至元三年冬先修宫城一说，长文并存不裁', '');
  l('p:劉秉忠', '营造', 'ev:元大都', '库内 yl 引《元史》卷一五七：「四年，又命秉忠築中都城，始建宗廟宮室」', 1, '其本传把改名年作八年，与本纪、地理志的九年不合，长文两说并存', '');
  l('p:张柔', '营造', 'ev:元大都', '库内 yl 引《元史》卷六世祖本纪：「詔安肅公張柔、行工部尚書段天祐等同行工部事，修築宮城」', 1, '至元三年十二月诏。同诏另出段天祐，中文维基无其条目（API 实测 missing），不另立', '');
  l('p:亦黑迭儿丁', '营造', 'ev:元大都', '库内 yl：「也黑迭儿设计宫殿、郭守敬任都水监引通惠河两事出中文维基本条转述层」', 2, '长文自标转述层，故层级2；维基正题作亦黑迭儿丁（也黑迭兒丁重定向至此），该条自述「他主持设计了元大都」', '');
  l('r:妥懽帖睦尔@yuan', '当事', 'ev:元大都', '库内 yl 引《元史》卷四十七顺帝本纪：「至夜半，開健德門北奔」', 1, '至正二十八年（1368）。健德门是北垣西门，在同卷地理志所列十一门之内', '');
  l('p:徐達', '当事', 'ev:元大都', '库内 yl 引《明史》卷一二五徐达传：「逾日，達陳兵齊化門，填濠登城」', 1, '齐化门是东垣南门。长文落句：一队人从健德门出去，一队人从齐化门进来，中间隔了一天', '');
  l('r:朱元璋@ming', '命名', 'ev:元大都', '库内 yl 引《明史》卷二太祖本纪：「壬午，幸北京。改大都路曰北平府」', 1, '本条 y2 取1368即此。长文警告同句「北京」指洪武初年以开封为北京，不是今北京。闭集无命名一族，动词拟新', '');
  l('p:徐達', '营造', 'ev:山海关', '库内 yc：「明洪武十四年（1381）徐达在此筑关设卫」', 1, '本条锚年即此；同一人另在库内元大都条以陈兵齐化门当事', '');
  l('p:吴三桂', '当事', 'ev:山海关', '库内 yc：「崇祯十七年（1644）吴三桂开关引清兵入塞」', 1, '长文落句「一座为挡人而筑的关，最后是被从里面打开的」；库内「冲冠一怒为红颜」条落点即山海关区', '');
  l('p:李新 (崇山侯)', '营造', 'ev:明孝陵', '库内 yl 引《明史》卷一三二：「十五年以营孝陵封崇山侯，岁禄千五百石」', 1, '督工者。受封月份《钦定续文献通考》作洪武十五年十二月、另有十一月一说，长文两存；维基裸名李新为消歧义页，正名取李新 (崇山侯)', '');
  l('p:孝慈高皇后 (明朝)', '当事', 'ev:明孝陵', '库内 yl 引《明史》卷三太祖本纪：「九月……庚午，葬孝慈皇后于孝陵」', 1, '本条锚年1382即此。陵名的「孝」出其谥号孝慈，长文作「这座陵是先有皇后葬进去，才有名字的」', '');
  l('r:朱元璋@ming', '当事', 'ev:明孝陵', '库内 yl：「洪武三十一年闰五月太祖崩，同月辛卯（1398-06-30）葬此」', 1, '遗诏「丧祭仪物，毋用金玉。孝陵山川因其故，毋改作」。长文不取通行的1381动工说，一手只坐实到1382', '');
  l('r:朱棣@ming', '敕修', 'ev:明十三陵', '库内 yl 引《明史》卷六成祖本纪：「五月己卯，營山陵於昌平，封其山曰天壽」', 1, '本条锚年1409即此；长陵动土比永乐十九年迁都早十二年', '');
  l('r:朱棣@ming', '命名', 'ev:明十三陵', '库内 yl 引《明史》卷六成祖本纪：「五月己卯，營山陵於昌平，封其山曰天壽」', 1, '同句两事：动土与钦定山名。下旨营陵与钦封山名是两个事实，照简报不合并', '');
  l('r:朱高炽@ming', '当事', 'ev:明十三陵', '库内 yl：「但自從明仁宗為其父朱棣寫了一篇3500字的紀功碑文後，再也沒有嗣皇帝續寫」', 2, '撰长陵神功圣德碑文，余陵遂皆无字碑。长文标此段为中文维基该条逐字，非一手，故层级2', '');
  l('r:朱棣@ming', '敕修', 'ev:天安门', '库内 yl：「明永乐十五年（1417）始建、十八年（1420）建成，仿南京承天门之制」', 1, '本条起年即此，初名承天门。长文未直书帝名，据永乐系成祖', '');
  l('p:白圭 (明朝)', '营造', 'ev:天安门', '库内 yl：「成化元年（1465）由工部尚书白圭主持、蒯祥设计重建」', 1, '天顺元年毁于雷火后的重建，自牌坊改成九间五进重檐歇山城楼，今日形制自此定；维基裸名白圭为消歧义页', '');
